(()=>{
/* Bài 4 — Vòng lặp for (chuẩn tường minh, 19/10/2026)
   Bối cảnh: quầy trà sữa của lớp tại Lễ hội Mùa Xuân phải làm cùng một việc nhiều lần.
   Tiết 1 = Chặng 1 (for lặp n lần, 3 phần của for, dùng i), tiết 2 = Chặng 2 (biến tổng cộng dồn, n nhập từ cin)
   và Chặng chứng chỉ. Mỗi chặng 6 tab (VAN_PHONG.md): Bối cảnh → Đoán rồi chạy → Kiểm chứng → Ghi nhớ → Luyện tập → Phản tư.
   Chuẩn câu hỏi: có tình huống, hỏi một ý, 4 phương án độ dài gần bằng nhau; mỗi phương án sai là một cách hiểu sai thường gặp.
   Bước chạy có bảng Bộ nhớ (i, tong), số nhập tô vàng (nhap) và dòng for tô xanh/đỏ khi kiểm tra điều kiện (kq).
*/
"use strict";

const { scratch, boiCanh, bang, ghiVo, luuY, chiTiet, timThem, sauTab, huongDanDoan, bonBuoc, tuCham } = window.KIT;
const strip = code => window.CPP.stripComments(code);
const khung = than => `#include <iostream>\nusing namespace std;\nint main() {\n${than}\n    return 0;\n}`;

/* ---------- đoạn code dùng xuyên suốt ---------- */
// Chặng 1: dán số thứ tự cho từng ly.
const LY = khung(`    for (int i = 1; i <= 3; i++) {
        cout << "Ly so " << i << endl;
    }
    cout << "Xong!";`);
const LY_LECH = LY.replace("i <= 3", "i < 3");
const MOI = khung(`    for (int i = 0; i < 4; i++) {
        cout << "Tra sua" << endl;
    }
    cout << "Xong!";`);
const MAN_LY = ["Ly so 1\nLy so 2\nLy so 3\nXong!", "Ly so i\nLy so i\nLy so i\nXong!", "Ly so 1\nXong!\nLy so 2\nXong!\nLy so 3\nXong!", "Ly so 1\nLy so 2\nLy so 3\nLy so 4\nXong!"];
const MAN_LECH = ["Ly so 1\nLy so 2\nLy so 3\nXong!", "Ly so 1\nLy so 2\nXong!", "Ly so 0\nLy so 1\nLy so 2\nXong!", "Ly so 1\nXong!"];
const MAN_MOI = ["Tra sua\nTra sua\nTra sua\nTra sua\nXong!", "Tra sua\nTra sua\nTra sua\nXong!", "Tra sua\nTra sua\nTra sua\nTra sua\nTra sua\nXong!", "Tra sua\nXong!"];
// Các bước của một vòng for: dòng for (khởi tạo hoặc bước tăng, rồi kiểm tra điều kiện), thân, …, dòng sau dấu }.
// dau: giá trị đầu của i; dk(i): điều kiện; chu(i): chữ của điều kiện; than(i): các bước trong thân; sau: các bước sau vòng lặp.
const vongFor = ({ dong, dau, buoc = 1, dk, chu, than, sau, mem0 = [] }) => {
  const s = [...mem0];
  let i = dau, lan = 0;
  for (;;) {
    const dung = dk(i);
    const mo = lan === 0 ? `Phần <strong>khởi tạo</strong> chạy một lần: tạo biến <code>i = ${dau}</code>.`
      : `Phần <strong>bước tăng</strong> chạy sau mỗi vòng: <code>i</code> ${buoc > 0 ? "tăng" : "giảm"} thành ${i}.`;
    s.push({ l: dong, kq: dung ? "t" : "f", mem: ["i", "int", String(i)],
      why: `${mo} Kiểm tra điều kiện <code>${chu(i)}</code>: ${dung ? "<strong>đúng</strong>, nên máy chạy thân vòng lặp." : "<strong>sai</strong>, nên vòng lặp dừng. Máy nhảy tới câu lệnh sau dấu <code>}</code>."}` });
    if (!dung) break;
    s.push(...than(i));
    lan++; i += buoc;
  }
  return s.concat(sau);
};
const traceLy = (dk, chu, gioi) => vongFor({ dong: 4, dau: 1, dk, chu,
  than: i => [{ l: 5, out: `Ly so ${i}\n`, why: `Thân vòng lặp: in chuỗi <code>"Ly so "</code> rồi in <strong>giá trị</strong> của <code>i</code> là ${i}, xuống dòng.` }],
  sau: [{ l: 7, out: "Xong!", why: `Dòng 7 nằm sau dấu <code>}</code> của vòng lặp, nên chạy <strong>một lần</strong>, sau khi vòng lặp đã dừng.` },
        { l: 8, why: "<code>return 0;</code> kết thúc chương trình." }] });

const SO_THU_TU_LOI = khung(`    for (int i = 1; i < 5; i++) {
        cout << "Ly so " << "i" << endl;
    }
    cout << "Xong!";`);

// Chặng 2: cộng dồn doanh thu.
const TONG = khung(`    int tong = 0;
    for (int i = 1; i <= 3; i++) {
        tong = tong + 25000;
    }
    cout << "Doanh thu: " << tong;`);
const TONG_TRONG = khung(`    int tong = 0;
    for (int i = 1; i <= 3; i++) {
        tong = tong + 25000;
        cout << "Doanh thu: " << tong << endl;
    }`);
const NGAY = khung(`    int n;
    cout << "Nhap so ngay: ";
    cin >> n;
    int tong = 0;
    for (int i = 1; i <= n; i++) {
        tong = tong + 30;
    }
    cout << "Tong so ly: " << tong;`);
const congDon = (dong, gia, them = () => []) => i => [
  { l: dong, mem: ["tong", "int", String(gia * i)], why: `Cộng dồn: lấy giá trị cũ của <code>tong</code> (${gia * (i - 1)}) cộng ${gia}, được ${gia * i}, rồi cất lại vào <code>tong</code>.` },
  ...them(i)];
const traceTong = vongFor({ dong: 5, dau: 1, dk: i => i <= 3, chu: i => `${i} <= 3`,
  mem0: [{ l: 4, mem: ["tong", "int", "0"], why: "Khai báo biến tổng <code>tong</code> và gán giá trị 0, ở <strong>trước</strong> vòng lặp." }],
  than: congDon(6, 25000),
  sau: [{ l: 8, out: "Doanh thu: 75000", why: "Dòng 8 nằm sau vòng lặp, chạy một lần: in tổng cuối cùng là 75000." },
        { l: 9, why: "<code>return 0;</code> kết thúc chương trình." }] });
const traceTrong = vongFor({ dong: 5, dau: 1, dk: i => i <= 3, chu: i => `${i} <= 3`,
  mem0: [{ l: 4, mem: ["tong", "int", "0"], why: "Khai báo <code>tong</code> và gán giá trị 0." }],
  than: congDon(6, 25000, i => [{ l: 7, out: `Doanh thu: ${25000 * i}\n`, why: `Câu lệnh cout nằm <strong>trong</strong> thân vòng lặp, nên chạy ở mỗi vòng: in giá trị hiện tại của <code>tong</code> là ${25000 * i}.` }]),
  sau: [{ l: 9, why: "<code>return 0;</code> kết thúc chương trình." }] });
const traceNgay = vongFor({ dong: 8, dau: 1, dk: i => i <= 4, chu: i => `${i} <= n` + ` (n = 4)`,
  mem0: [{ l: 4, mem: ["n", "int", "?"], why: "Khai báo biến <code>n</code> lưu số ngày." },
         { l: 5, out: "Nhap so ngay: ", why: "In câu dẫn." },
         { l: 6, nhap: "4", mem: ["n", "int", "4"], why: "Khách gõ <code>4</code> rồi bấm Enter, <code>cin</code> lưu 4 vào <code>n</code>. Số lần lặp phụ thuộc vào n." },
         { l: 7, mem: ["tong", "int", "0"], why: "Khai báo biến tổng và gán 0, ở trước vòng lặp." }],
  than: congDon(9, 30),
  sau: [{ l: 11, out: "Tong so ly: 120", why: "Sau 4 vòng, tong = 30 + 30 + 30 + 30 = 120. Dòng 11 in tổng một lần." },
        { l: 12, why: "<code>return 0;</code> kết thúc chương trình." }] });

const TONG_NGAY_KHUNG = khung(`    int n;
    cout << "Nhap so ngay: ";
    cin >> n;
    int tong = 0;
    // Viet vong lap for cong don o day: ngay i ban i ly

    cout << "Tong so ly: " << tong;`);
const BANG_GIA_KHUNG = khung(`    int n;
    cout << "Nhap so ly toi da: ";
    cin >> n;
    // In bang gia tu 1 ly den n ly, moi ly 25000
`);
const CHAN_KHUNG = khung(`    int n;
    cout << "Nhap n: ";
    cin >> n;
    // In cac so chan tu 1 den n, moi so mot dong
`);

const BON_BUOC_1 = bonBuoc([["Hiểu đề", "việc gì lặp lại, lặp mấy lần, mỗi lần in gì?"],
  ["Chọn biến", "biến đếm <code>i</code> kiểu <code>int</code>: bắt đầu từ đâu, dừng ở đâu?"],
  ["Viết màn hình mong đợi trước", "đếm số dòng màn hình phải hiện, chép ra giấy."],
  ["Viết, chạy, so sánh, sửa", "chạy chương trình, đếm số dòng in ra, so với màn hình mong đợi rồi sửa."]]);
const BON_BUOC_2 = bonBuoc([["Hiểu đề", "lặp mấy lần, mỗi vòng cộng thêm gì vào tổng, in gì ở cuối?"],
  ["Chọn biến", "biến đếm <code>i</code>, biến tổng <code>tong</code> (khởi tạo 0 ở trước vòng lặp), kiểu <code>int</code>."],
  ["Thiết kế test case trước khi viết", "n = 0 (không lặp lần nào), n = 1 và một n bình thường; tính tay kết quả."],
  ["Viết, chạy, so sánh, sửa", "chạy với từng test case, so màn hình với kết quả đã tính tay."]]);

window.LESSON = {
  id: "bai04",
  chuan: 2,
  number: 4,
  title: "Vòng lặp for",
  story: "Quầy trà sữa làm việc lặp lại",
  badge: { icon: "🔁", name: "Người điều khiển dây chuyền" },
  skills: ["Vòng lặp for", "Ba phần của for", "Biến đếm i", "Đếm ngược, bước nhảy", "Biến tổng cộng dồn", "Kiểm thử n = 0, 1"],
  certNote: "Nộp kèm: ảnh bài làm nhóm và bài cá nhân trên Programiz",

  errorTable: [
    ["Thiếu một dòng (in 1 đến 4 thay vì 5)", "Dùng <code>i &lt; 5</code> thay vì <code>i &lt;= 5</code>", "Lặp n lần từ 1: <code>i &lt;= n</code>; luôn đếm số dòng in ra"],
    ["Thân vòng lặp chỉ chạy một lần", "Có dấu <code>;</code> ngay sau <code>for (…)</code>", "Xoá dấu <code>;</code> đứng sau dấu <code>)</code>"],
    ["In chữ i thay vì số", "Đặt i trong dấu ngoặc kép: <code>cout &lt;&lt; \"i\";</code>", "In giá trị: <code>cout &lt;&lt; i;</code>"],
    ["Tổng chỉ bằng giá trị của vòng cuối", "Khai báo <code>int tong = 0;</code> bên trong vòng lặp", "Khai báo biến tổng ở trước vòng lặp"],
    ["Vòng lặp không dừng", "Bước tăng đi sai hướng (đếm lên mà dùng <code>i--</code>)", "Đếm lên dùng <code>i++</code>, đếm xuống dùng <code>i--</code>"],
    ["Máy báo không biết tên “cout”", "Thiếu <code>using namespace std;</code>", "Thêm ngay sau <code>#include &lt;iostream&gt;</code>"]
  ],

  steps: [
    /* ================= CHẶNG 1 · TIẾT 1 · for ================= */
    {
      kind: "stage", id: "stage-1", number: 1, nav: "Chặng 1",
      kicker: "CHẶNG 1 · TIẾT 1 · VÒNG LẶP for",
      title: "Dán số thứ tự cho từng ly",
      bit: "Chào bạn! Chặng này có 6 phần. Làm xong mỗi phần, bấm <strong>Tiếp</strong> ở cuối trang.",
      objectives: ["Đọc vòng lặp for và đếm đúng số lần lặp",
        "Gọi tên 3 phần của for: khởi tạo, điều kiện, bước tăng",
        "Dùng biến đếm i trong thân vòng lặp"],
      flow: [
        { label: "Bối cảnh", title: "Quầy cần dán số cho 100 ly",
          html: boiCanh("Sáng nay quầy pha 100 ly trà sữa. Mỗi ly cần dán nhãn số thứ tự: Ly so 1, Ly so 2, …, Ly so 100.",
            `<p>Nếu viết một câu lệnh <code>cout</code> cho mỗi nhãn, chương trình sẽ có 100 câu lệnh gần giống nhau. Lập trình viên không làm vậy: họ dùng <strong>vòng lặp</strong>, câu lệnh giúp máy lặp lại một nhóm câu lệnh nhiều lần. Trong C++, vòng lặp hay dùng nhất khi biết trước số lần lặp là <strong>vòng lặp for</strong>.</p>
             <p>Ở chặng này, bạn sẽ chạy từng bước ba vòng lặp nhỏ, theo dõi giá trị của biến đếm <code>i</code> trong bảng <strong>Bộ nhớ</strong>, rồi tự sửa máy dán nhãn đang bị thiếu một nhãn.</p>`) + sauTab("Kiểm chứng") },
        { label: "Đoán rồi chạy", title: "Ba vòng lặp dán nhãn", tasks: ["c1-dc1", "c1-dc2", "c1-dc3"],
          html: huongDanDoan(3) + `<p>Ở dòng <code>for</code>, mỗi lần máy kiểm tra điều kiện, dòng code được tô <strong style="color:#166534">xanh</strong> nếu điều kiện đúng (lặp tiếp) và <strong style="color:#991b1b">đỏ</strong> nếu sai (dừng).</p>`,
          bit: "Đếm xem dòng for được kiểm tra mấy lần." },
        { label: "Kiểm chứng", title: "Vòng lặp chạy mấy lần?", tasks: ["c1-solan", "c1-baphan", "c1-dungsai"],
          code: LY, focus: [4],
          html: `<p>Khung bên trái là chương trình ở <strong>Lần 1</strong>. Dựa vào bảng Bộ nhớ và màn hình bạn vừa thấy, trả lời các câu hỏi bên cạnh.</p>` },
        { label: "Ghi nhớ", title: "Vòng lặp for",
          html: ghiVo(["<code>for (int i = 1; i &lt;= n; i++) { … }</code>: lặp thân vòng lặp n lần, i lần lượt là 1, 2, …, n.",
                "Ba phần của for: khởi tạo <code>int i = 1</code> (chạy một lần), điều kiện <code>i &lt;= n</code> (đúng thì lặp tiếp), bước tăng <code>i++</code> (sau mỗi vòng).",
                "Câu lệnh sau dấu <code>}</code> của vòng lặp chạy một lần, sau khi vòng lặp kết thúc."])
            + luuY("<code>i &lt; 3</code> chạy 2 lần (i = 1, 2) còn <code>i &lt;= 3</code> chạy 3 lần. Không đặt dấu <code>;</code> ngay sau <code>for (…)</code>.")
            + chiTiet
            + bang("1. Khái niệm", ["Thuật ngữ", "Định nghĩa", "Ví dụ"], [
              ["Vòng lặp", "Câu lệnh giúp máy thực hiện lặp lại một nhóm câu lệnh nhiều lần.", "<code>for</code>"],
              ["Thân vòng lặp", "Các câu lệnh trong cặp ngoặc <code>{ }</code> của vòng lặp, được chạy ở mỗi vòng.", "<code>cout &lt;&lt; \"Ly so \" &lt;&lt; i;</code>"],
              ["Biến đếm", "Biến thay đổi sau mỗi vòng, cho biết đang ở vòng thứ mấy.", "<code>i</code>"],
              ["Khởi tạo", "Phần đầu của for, chạy một lần lúc bắt đầu, thường tạo biến đếm.", "<code>int i = 1</code>"],
              ["Điều kiện lặp", "Phần giữa của for. Còn đúng thì chạy thân; sai thì dừng vòng lặp.", "<code>i &lt;= 3</code>"],
              ["Bước tăng", "Phần cuối của for, chạy sau mỗi vòng. <code>i++</code> nghĩa là <code>i = i + 1</code>.", "<code>i++</code>"]])
            + bang("2. Theo dõi biến đếm của <code>for (int i = 1; i &lt;= 3; i++)</code>", ["Lần kiểm tra", "Giá trị i", "<code>i &lt;= 3</code>", "Máy làm gì"], [
              ["1", "1", "đúng", "in <code>Ly so 1</code>"],
              ["2", "2", "đúng", "in <code>Ly so 2</code>"],
              ["3", "3", "đúng", "in <code>Ly so 3</code>"],
              ["4", "4", "sai", "dừng vòng lặp, chạy câu lệnh sau <code>}</code>"]])
            + scratch("repeat (3)\nsay [Ly so ...]\nend", "Vòng lặp for giống khối <em>lặp lại</em> trong Scratch, nhưng có thêm biến đếm i.")
            + timThem([["https://www.w3schools.com/cpp/cpp_for_loop.asp", "W3Schools · Vòng lặp for"],
                       ["https://www.programiz.com/cpp-programming/for-loop", "Programiz · for loop"],
                       ["https://www.learncpp.com/cpp-tutorial/for-statements/", "LearnCpp · Câu lệnh for"]]) },
        { label: "Luyện tập", title: "Điền, rồi sửa máy dán nhãn", tasks: ["c1-dien", "c1-sua"], html: BON_BUOC_1 },
        { label: "Phản tư", title: "Bạn đã chắc đến đâu?", tasks: ["c1-tucham"], stop: true,
          html: `<p>${tuCham}</p>`, bit: "Xong Chặng 1! Dừng lại và nhìn lên bảng." }
      ],
      challenges: [
        { id: "c1-dc1", type: "doanchay", predict: true, icon: "🔮",
          title: "Lần 1 · Dán nhãn 3 ly",
          prompt: "Vòng lặp ở dòng 4 dùng biến đếm <code>i</code> bắt đầu từ 1. Thân vòng lặp (dòng 5) in nhãn có giá trị của <code>i</code>.",
          ask: "Theo bạn, màn hình sẽ hiện gì?",
          code: LY, focus: [4], options: MAN_LY, answer: MAN_LY[0],
          trace: traceLy(i => i <= 3, i => `${i} <= 3`),
          whyRight: "Mỗi vòng i tăng 1, nên máy in Ly so 1, 2, 3 rồi mới in Xong! một lần.",
          why: "i nằm ngoài dấu ngoặc kép nên máy in giá trị của i: 1, 2, 3. Đến i = 4 thì điều kiện sai, vòng lặp dừng. Dòng 7 nằm sau dấu } nên chỉ chạy một lần." },
        { id: "c1-dc2", type: "doanchay", predict: true, icon: "🔮", after: "c1-dc1",
          title: "Lần 2 · Đổi <= thành <",
          prompt: "Chương trình này giống Lần 1, chỉ khác điều kiện ở dòng 4: <code>i &lt; 3</code> thay cho <code>i &lt;= 3</code>.",
          ask: "Theo bạn, lần này màn hình sẽ hiện gì?",
          code: LY_LECH, focus: [4], options: MAN_LECH, answer: MAN_LECH[1],
          trace: traceLy(i => i < 3, i => `${i} < 3`),
          whyRight: "Khi i = 3, 3 < 3 là sai, nên máy dừng sau 2 vòng.",
          why: "3 < 3 là sai, nên vòng lặp dừng khi i = 3. Máy chỉ in 2 nhãn. Đây là lỗi lệch một lần (off-by-one) rất hay gặp." },
        { id: "c1-dc3", type: "doanchay", predict: true, icon: "🔮", after: "c1-dc2",
          title: "Lần 3 · Bắt đầu từ 0",
          prompt: "Vòng lặp này bắt đầu từ <code>i = 0</code> và dùng điều kiện <code>i &lt; 4</code>. Thân vòng lặp in chữ Tra sua.",
          ask: "Theo bạn, máy in mấy dòng Tra sua?",
          code: MOI, focus: [4], options: MAN_MOI, answer: MAN_MOI[0],
